def path_has_tail(path_value, tail_value):
    normalized_path = str(path_value).replace('\\', '/').rstrip('/')
    normalized_tail = str(tail_value).replace('\\', '/').strip('/')
    return normalized_path == normalized_tail or normalized_path.endswith('/' + normalized_tail)
assert remaining_top_level_files == []
observed_directory_names = {str(path).replace('\\', '/').rstrip('/').split('/')[-1] for path in location_directories}
planned_city_names = {item['city'] for item in move_plan}
assert planned_city_names.issubset(observed_directory_names)
for move_item in move_plan:
    expected_tail = move_item['city'] + '/' + move_item['filename']
    assert any(path_has_tail(path, expected_tail) for path in recursive_vacation_files)
for move_item, destination_record in zip(move_plan, verified_destination_records):
    assert path_has_tail(destination_record['path'], move_item['city'] + '/' + move_item['filename'])
print({'remaining_top_level_files': remaining_top_level_files, 'location_directories': location_directories, 'verified_destination_paths': [record['path'] for record in verified_destination_records]})
